 const cleared=Object.values(state.world.adventures||{}).filter(x=>x.completed).length;
 const quests=(state.world.quests||[]).filter(x=>x.status==='complete').length;
 const fq=Object.values(state.world.factionQuestlines||{}).filter(x=>x.complete).length;
