function restoreActiveCompany(mult=1){
 state.guardian.hp=Math.max(state.guardian.hp,Math.round(maxHP()*mult));state.guardian.stamina=Math.max(state.guardian.stamina,Math.round(maxStamina()*mult));
 for(const m of partyMembers(true)){m.hp=Math.max(m.hp,Math.round(allyMaxHP(m)*mult));m.stamina=Math.max(m.stamina,Math.round(allyMaxStamina(m)*mult))}
}

function activeCompanyNeedsRecovery(){
 if(state.guardian.hp<maxHP()||state.guardian.stamina<maxStamina())return true;
 return partyMembers(true).some(m=>m.hp<allyMaxHP(m)||m.stamina<allyMaxStamina(m))
}
function activeCompanyRecoverySummary(){
 const rows=[];
 if(state.guardian.hp<maxHP()||state.guardian.stamina<maxStamina())rows.push(SOSText("companions_stories_settlement_services.activeCompanyRecoverySummary.001",state.name,state.guardian.hp,maxHP(),state.guardian.stamina,maxStamina()));
 for(const m of partyMembers(true))if(m.hp<allyMaxHP(m)||m.stamina<allyMaxStamina(m))rows.push(SOSText("companions_stories_settlement_services.activeCompanyRecoverySummary.002",m.name,m.hp,allyMaxHP(m),m.stamina,allyMaxStamina(m)));
 return rows
}
